  1→import { useTranslation } from '../hooks/useTranslation';
  2→import type { ToolCallResult } from '../types';
  3→import './InlineQueryResult.css';
  4→import { ChartWidget } from './ChartWidget';
  5→
  6→const MAX_DISPLAY_ROWS = 20;
  7→
  8→function getToolDisplayName(result: ToolCallResult, t: (key: string) => string): string {
  9→  const name = result.toolName || '';
 10→  if (name.includes('execute_sql')) return t('sqlQuery');
 11→  if (name === 'Bash') return t('bash');
 12→  if (name === 'Read') return t('readFile');
 13→  if (name === 'Write') return t('writeFile');
 14→  if (name === 'Edit') return t('editFile');
 15→  if (name.startsWith('mcp__')) {
 16→    const parts = name.split('__');
 17→    return parts[parts.length - 1] || name;
 18→  }
 19→  return name || 'Tool';
 20→}
 21→
 22→function getToolInputDisplay(result: ToolCallResult): string | null {
 23→  if (result.sql) return result.sql;
 24→  if (result.command) return result.command;
 25→  if (result.toolInput) {
 26→    const entries = Object.entries(result.toolInput);
 27→    if (entries.length === 0) return null;
 28→    // For single-value inputs, show just the value
 29→    if (entries.length === 1) {
 30→      const val = entries[0][1];
 31→      if (val === null || val === undefined) return '';
 32→      if (typeof val === 'object') return JSON.stringify(val, null, 2);
 33→      return String(val);
 34→    }
 35→    return JSON.stringify(result.toolInput, null, 2);
 36→  }
 37→  return null;
 38→}
 39→
 40→function isSQL(result: ToolCallResult): boolean {
 41→  return !!result.sql && (result.toolName?.includes('execute_sql') ?? false);
 42→}
 43→
 44→export function InlineQueryResult({ result }: { result: ToolCallResult }) {
 45→  const { t } = useTranslation();
 46→  const displayName = getToolDisplayName(result, t);
 47→  const inputDisplay = getToolInputDisplay(result);
 48→  const isSQLTool = isSQL(result);
 49→  const hasStructuredData = result.columns.length > 0;
 50→  const displayRows = result.rows.slice(0, MAX_DISPLAY_ROWS);
 51→
 52→  // Render chart if chart_spec is present
 53→  if (result.chart_spec) {
 54→    return (
 55→      <div className="inline-query inline-query--chart">
 56→        <div className="inline-query__label inline-query__label--generic">
 57→          {getToolDisplayName(result, t)}
 58→        </div>
 59→        <ChartWidget
 60→          data={result.chart_spec.data}
 61→          layout={result.chart_spec.layout}
 62→          frames={result.chart_spec.frames}
 63→        />
 64→      </div>
 65→    );
 66→  }
 67→
 68→  // Determine border color class
 69→  let variantClass = '';
 70→  if (result.error) variantClass = 'inline-query--error';
 71→  else if (result.command) variantClass = 'inline-query--bash';
 72→  else if (!isSQLTool && !result.sql) variantClass = 'inline-query--generic';
 73→
 74→  return (
 75→    <div className={`inline-query ${variantClass}`}>
 76→      {/* Tool label */}
 77→      <div className={`inline-query__label ${isSQLTool ? 'inline-query__label--sql' : result.command ? 'inline-query__label--bash' : 'inline-query__label--generic'}`}>
 78→        {displayName}
 79→      </div>
 80→
 81→      {/* Tool input */}
 82→      {inputDisplay && (
 83→        <div className="inline-query__sql">
 84→          <code>{inputDisplay}</code>
 85→        </div>
 86→      )}
 87→
 88→      {/* Error display */}
 89→      {result.error && (
 90→        <div className="inline-query__error">{result.error}</div>
 91→      )}
 92→
 93→      {/* SQL structured results */}
 94→      {!result.error && isSQLTool && hasStructuredData && (
 95→        <>
 96→          <div className="inline-query__table-wrapper">
 97→            <table className="inline-query__table">
 98→              <thead>
 99→                <tr>
100→                  {result.columns.map((col) => (
101→                    <th key={col}>{col}</th>
102→                  ))}
103→                </tr>
104→              </thead>
105→              <tbody>
106→                {displayRows.map((row, i) => (
107→                  <tr key={i}>
108→                    {result.columns.map((col) => (
109→                      <td key={col}>{String(row[col] ?? '')}</td>
110→                    ))}
111→                  </tr>
112→                ))}
113→              </tbody>
114→            </table>
115→          </div>
116→          <div className="inline-query__meta">
117→            {t('rowCount', { count: result.rowCount })}
118→            {result.rowCount > MAX_DISPLAY_ROWS && ` ${t('showingCount', { count: MAX_DISPLAY_ROWS })}`}
119→          </div>
120→        </>
121→      )}
122→
123→      {/* Text output for non-SQL tools */}
124→      {!result.error && result.output && (
125→        <div className="inline-query__output">
126→          <pre>{result.output}</pre>
127→        </div>
128→      )}
129→
130→      {/* Raw content fallback */}
131→      {!result.error && !hasStructuredData && !result.output && result.rawContent && (
132→        <div className="inline-query__raw">
133→          <pre>{result.rawContent}</pre>
134→        </div>
135→      )}
136→
137→      {/* Pending state */}
138→      {!result.error && !hasStructuredData && !result.output && !result.rawContent && inputDisplay && (
139→        <div className="inline-query__meta">{t('executing')}</div>
140→      )}
141→    </div>
142→  );
143→}
