file.content:
.inline-query {
  margin: 8px 0;
  border: 1px solid var(--color-border-light);
  border-radius: 8px;
  overflow: hidden;
  font-size: 12px;
}

.inline-query--error {
  border-color: var(--color-error-border);
}

.inline-query--bash {
  border-color: var(--color-tool-bash-border);
}

.inline-query--generic {
  border-color: var(--color-tool-generic-border);
}

.inline-query--chart {
  overflow: visible;
}

/* Tool label */
.inline-query__label {
  display: flex;
  align-items: center;
  padding: 3px 10px;
  font-size: 11px;
  font-weight: 600;
  border-bottom: 1px solid var(--color-border-light);
}

.inline-query__label--sql {
  color: var(--color-success-text-dark);
  background: var(--color-success-bg-alt);
  border-bottom-color: var(--color-success-border-light);
}

.inline-query__label--bash {
  color: var(--color-tool-bash-text);
  background: var(--color-tool-bash-bg);
  border-bottom-color: var(--color-tool-bash-border);
}

.inline-query__label--generic {
  color: var(--color-tool-generic-text);
  background: var(--color-tool-generic-bg);
  border-bottom-color: var(--color-tool-generic-border);
}

/* Copy button */
.inline-query__copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px;
  border-radius: 3px;
  color: var(--color-text-disabled);
  line-height: 1;
  flex-shrink: 0;
}

.inline-query__label .inline-query__copy-btn {
  margin-left: auto;
}

.inline-query__copy-btn:hover {
  background: var(--color-border-light);
  color: var(--color-text-tertiary);
}

/* Tool input (SQL, command, etc.) */
.inline-query__sql {
  position: relative;
  padding: 6px 10px;
  background: var(--color-bg-code);
  border-bottom: 1px solid var(--color-border-light);
  overflow-x: auto;
}

.inline-query__sql .inline-query__copy-btn {
  position: absolute;
  top: 4px;
  right: 4px;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.inline-query__sql:hover .inline-query__copy-btn {
  opacity: 1;
}

.inline-query__sql code {
  font-size: 12px;
  color: var(--color-text-code);
  white-space: pre-wrap;
  word-break: break-all;
}

.inline-query__error {
  padding: 8px 10px;
  color: var(--color-error-text);
  background: var(--color-error-bg);
}

.inline-query__table-wrapper {
  overflow-x: auto;
  max-height: 300px;
  overflow-y: auto;
}

.inline-query__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.inline-query__table th,
.inline-query__table td {
  padding: 4px 8px;
  text-align: left;
  border-bottom: 1px solid var(--color-bg-code);
  white-space: nowrap;
}

.inline-query__table th {
  background: var(--color-bg-secondary);
  font-weight: 600;
  color: var(--color-text-tertiary);
  position: sticky;
  top: 0;
}

.inline-query__table td {
  color: var(--color-text-code);
}

.inline-query__meta {
  padding: 4px 10px;
  font-size: 11px;
  color: var(--color-text-disabled);
  background: var(--color-bg-secondary);
  border-top: 1px solid var(--color-border-light);
}

/* Text output for non-SQL tools */
.inline-query__output {
  padding: 8px 10px;
  overflow-x: auto;
  max-height: 300px;
  overflow-y: auto;
  background: var(--color-bg-secondary);
}

.inline-query__output pre {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-tertiary);
  white-space: pre-wrap;
  word-break: break-word;
}

.inline-query__raw {
  padding: 8px 10px;
  overflow-x: auto;
}

.inline-query__raw pre {
  margin: 0;
  font-size: 12px;
  color: var(--color-text-code);
  white-space: pre-wrap;
  word-break: break-word;
}

